"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

export default function DashboardPage() {
  const [user, setUser] = useState(null);
  const router = useRouter();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      router.push("/login");
      return;
    }
    try {
      const payload = JSON.parse(atob(token.split(".")[1]));
      setUser(payload);
    } catch {
      localStorage.removeItem("token");
      router.push("/login");
    }
  }, [router]);

  const handleLogout = () => {
    localStorage.removeItem("token");
    router.push("/login");
  };

  if (!user) return null;
console.log("user",user);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white p-8 rounded shadow-md w-96">
        <h2 className="text-2xl font-bold mb-4">Patient Dashboard</h2>
        <p className="mb-2">Welcome, <span className="font-semibold">{user.fullName}</span>!</p>
        <p className="mb-4">User ID: <span className="text-gray-600">{user.userId}</span></p>
        <button onClick={handleLogout} className="w-full bg-red-600 text-white p-2 rounded hover:bg-red-700">Logout</button>
      </div>
    </div>
  );
} 